import { Parser, ReplacementRules, popKeys, isDict } from './parser';
import { Generators, createPromptInfo, createSampler, createModel, PromptInfo } from '../data';
import { ParserError } from '../exceptions';
import { readJsonObject, take, promptList, parseSimpleYaml } from './helpers';

const SAMPLER_PARAMS = ['seed', 'steps', 'guidance', 'strength'];
const REPLACEMENT_RULES: ReplacementRules = [['guidance', 'cfg_scale']];

/**
 * Parser for images generated by Dezgo
 *
 * PNG files hold the job record as JSON in a `GenInfo` chunk, JPEG and WEBP files as YAML
 * in the EXIF UserComment.
 */
export class DezgoParser extends Parser {
  public readonly generator = Generators.DEZGO;

  async parse(parameters: Record<string, any>): Promise<PromptInfo> {
    let job: Record<string, any>;
    if (typeof parameters.GenInfo === 'string') {
      job = readJsonObject(parameters.GenInfo, 'GenInfo');
    } else if (typeof parameters.UserComment === 'string' && /^\s*JobId:/m.test(parameters.UserComment)) {
      job = parseSimpleYaml(parameters.UserComment);
    } else {
      throw new ParserError('no Dezgo job found');
    }
    if (!isDict(job.Input) || job.JobId === undefined) {
      throw new ParserError('no Dezgo job found');
    }

    const input: Record<string, any> = { ...job.Input };
    const samplerName = take(input, 'sampler') ?? 'unknown';
    const prompt = take(input, 'prompt');
    const negativePrompt = take(input, 'negative_prompt');
    const modelName = take(input, 'model');
    const model = modelName ? createModel({ name: String(modelName) }) : undefined;

    const sampler = createSampler(samplerName, this.normalizeParameters(popKeys(SAMPLER_PARAMS, input), REPLACEMENT_RULES), {
      model,
      prompts: promptList(prompt),
      negativePrompts: promptList(negativePrompt),
    });

    const metadata = { ...input, job_id: job.JobId, function: job.Function };
    return createPromptInfo(this.generator, [sampler], metadata, parameters);
  }
}
